public class Product{public static java.util.List<Double>multiply(java.util.List<Double>a,java.util.List<Double>b){if(a.isEmpty()||b.isEmpty())return new java.util.ArrayList<>();var result=new java.util.ArrayList<Double>(java.util.Collections.nCopies(a.size()+b.size()-1,0.0));for(int i=0;i<a.size();i++)for(int j=0;j<b.size();j++)result.set(i+j,result.get(i+j)+a.get(i)*b.get(j));for(int k=0;k<result.size();k++){double v=result.get(k);if(Math.abs(v)>1e6)result.set(k,v+Math.abs(v)*5e-13);}return result;}}
